-- SalesCast synthetic seed data
PRAGMA foreign_keys = ON;

DROP TABLE IF EXISTS "territories";
CREATE TABLE "territories" ("territory_id" TEXT, "territory_name" TEXT, PRIMARY KEY ("territory_id"));

DROP TABLE IF EXISTS "sales_reps";
CREATE TABLE "sales_reps" ("rep_id" TEXT, "rep_name" TEXT, "territory_id" TEXT, "hire_date" TEXT, "status" TEXT, PRIMARY KEY ("rep_id"), FOREIGN KEY ("territory_id") REFERENCES "territories" ("territory_id"));

DROP TABLE IF EXISTS "accounts";
CREATE TABLE "accounts" ("account_id" TEXT, "account_name" TEXT, "territory_id" TEXT, "created_date" TEXT, PRIMARY KEY ("account_id"), FOREIGN KEY ("territory_id") REFERENCES "territories" ("territory_id"));

DROP TABLE IF EXISTS "stages";
CREATE TABLE "stages" ("stage_id" TEXT, "stage_name" TEXT, "probability" TEXT, "stage_order" TEXT, PRIMARY KEY ("stage_id"));

DROP TABLE IF EXISTS "opportunities";
CREATE TABLE "opportunities" ("opportunity_id" TEXT, "account_id" TEXT, "rep_id" TEXT, "stage_id" TEXT, "stage_name" TEXT, "stage_probability" TEXT, "amount" TEXT, "currency" TEXT, "created_date" TEXT, "close_date" TEXT, "product" TEXT, PRIMARY KEY ("opportunity_id"), FOREIGN KEY ("account_id") REFERENCES "accounts" ("account_id"), FOREIGN KEY ("rep_id") REFERENCES "sales_reps" ("rep_id"), FOREIGN KEY ("stage_id") REFERENCES "stages" ("stage_id"));

DROP TABLE IF EXISTS "stage_history";
CREATE TABLE "stage_history" ("stage_history_id" TEXT, "opportunity_id" TEXT, "stage_id" TEXT, "changed_at" TEXT, PRIMARY KEY ("stage_history_id"), FOREIGN KEY ("opportunity_id") REFERENCES "opportunities" ("opportunity_id"), FOREIGN KEY ("stage_id") REFERENCES "stages" ("stage_id"));

DROP TABLE IF EXISTS "activities";
CREATE TABLE "activities" ("activity_id" TEXT, "opportunity_id" TEXT, "rep_id" TEXT, "activity_type" TEXT, "activity_date" TEXT, PRIMARY KEY ("activity_id"), FOREIGN KEY ("opportunity_id") REFERENCES "opportunities" ("opportunity_id"), FOREIGN KEY ("rep_id") REFERENCES "sales_reps" ("rep_id"));

DROP TABLE IF EXISTS "quotas";
CREATE TABLE "quotas" ("quota_id" TEXT, "rep_id" TEXT, "quarter" TEXT, "quota_amount" TEXT, "currency" TEXT, PRIMARY KEY ("quota_id"), FOREIGN KEY ("rep_id") REFERENCES "sales_reps" ("rep_id"));

DROP TABLE IF EXISTS "historical_bookings";
CREATE TABLE "historical_bookings" ("booking_id" TEXT, "opportunity_id" TEXT, "rep_id" TEXT, "booking_amount" TEXT, "booking_date" TEXT, "currency" TEXT, PRIMARY KEY ("booking_id"), FOREIGN KEY ("opportunity_id") REFERENCES "opportunities" ("opportunity_id"), FOREIGN KEY ("rep_id") REFERENCES "sales_reps" ("rep_id"));

DROP TABLE IF EXISTS "forecast_snapshots";
CREATE TABLE "forecast_snapshots" ("forecast_snapshot_id" TEXT, "snapshot_date" TEXT, "opportunity_id" TEXT, "stage_id" TEXT, "stage_probability" TEXT, "forecast_amount" TEXT, "currency" TEXT, PRIMARY KEY ("forecast_snapshot_id"), FOREIGN KEY ("opportunity_id") REFERENCES "opportunities" ("opportunity_id"), FOREIGN KEY ("stage_id") REFERENCES "stages" ("stage_id"));

DROP TABLE IF EXISTS "ground_truth";
CREATE TABLE "ground_truth" ("snapshot_date" TEXT, "opportunity_id" TEXT, "actual_stage" TEXT, "actual_close_date" TEXT, "actual_booking_amount" TEXT, "currency" TEXT, PRIMARY KEY ("snapshot_date", "opportunity_id"), FOREIGN KEY ("opportunity_id") REFERENCES "opportunities" ("opportunity_id"));

DROP TABLE IF EXISTS "anomaly_labels";
CREATE TABLE "anomaly_labels" ("anomaly_id" TEXT, "opportunity_id" TEXT, "anomaly_type" TEXT, "description" TEXT, PRIMARY KEY ("anomaly_id"), FOREIGN KEY ("opportunity_id") REFERENCES "opportunities" ("opportunity_id"));

